package com.archway.estore.util;import java.text.SimpleDateFormat;import java.util.Calendar;/** *  * Archway Marketing Services. * 7525 Cogswell Rd, * Romulus, MI - 48174. * Phone - 734.713.2000 *  * Project Name            : FordKeyCode *  * Author                  : bhattam0 - Amar Bhatt Email:(AMAR_BHATT@ARCHWAY.COM) PH. 734.713.2019 * File Name               : Format.java  * Package Name            : com.archway.estore.util *  * Date                    : Jan 20, 2014 9:03:13 PM *  * Change Date             : Jan 20, 2014 9:03:13 PM * 							  * --------------------------------------------------------- * Description :- Add Class Description here * --------------------------------------------------------- */public class Format{	/*	 * static{ if(!LogConfig.isLogging()){ LogConfig.initLogging(); } cat =	 * Category.getInstance(com.archway.estore.util.Format.class); }	 */	private static final SimpleDateFormat	sdfDate	= new SimpleDateFormat ( "MM/dd/yyyy" );	/**	 * Format constructor comment.	 */	public Format ()	{		super ();	}	/**	 * Insert the method's description here. Creation date: (9/19/01 4:29:32 PM)	 * 	 * @return java.lang.String	 * @param aDate	 *            java.util.Date	 */	public static String formatDate ( java.util.Date aDate )	{		if ( aDate != null )			return sdfDate.format ( aDate );		else			return null;	}	public static String getCurrentDateString ()	{		return formatDate ( new java.util.Date () );	}	public static String getAdjustedDate ( int calendarField , int adjustment )	{		Calendar cal = Calendar.getInstance ();		cal.setTime ( new java.util.Date () );		cal.add ( calendarField , adjustment );		return formatDate ( cal.getTime () );	}	public static String getScriptSafeString ( String s )	{		int startIndex = 0;		int lastIndex = 0;		StringBuffer newString = new StringBuffer ();		while ( s.indexOf ( "'" , startIndex ) >= 0 )		{			lastIndex = s.indexOf ( "'" , startIndex );			newString.append ( s.substring ( startIndex , lastIndex ) );			newString.append ( '\\' );			newString.append ( "'" );			startIndex = lastIndex + 1;		}		newString.append ( s.substring ( startIndex ) );		return newString.toString ();	}	public static String getRequestSafeString ( String s )	{		int startIndex = 0;		int lastIndex = 0;		StringBuffer newString = new StringBuffer ();		while ( s.indexOf ( "&" , startIndex ) >= 0 )		{			lastIndex = s.indexOf ( "&" , startIndex );			if ( s.charAt ( lastIndex - 1 ) == ' ' && s.charAt ( lastIndex + 1 ) == ' ' )			{				newString.append ( s.substring ( startIndex , lastIndex ) );				newString.append ( "%26" );			}			else			{				newString.append ( s.substring ( startIndex , lastIndex + 1 ) );			}			startIndex = lastIndex + 1;		}		newString.append ( s.substring ( startIndex ) );		s = newString.toString ();		newString = new StringBuffer ();		startIndex = 0;		lastIndex = 0;		newString = new StringBuffer ();		while ( s.indexOf ( " " , startIndex ) >= 0 )		{			lastIndex = s.indexOf ( " " , startIndex );			newString.append ( s.substring ( startIndex , lastIndex ) );			newString.append ( "%20" );			startIndex = lastIndex + 1;		}		newString.append ( s.substring ( startIndex ) );		return newString.toString ();	}	public static String getReformattedString ( String s )	{		int startIndex = 0;		int lastIndex = 0;		StringBuffer newString = new StringBuffer ();		while ( s.indexOf ( "%20" , startIndex ) >= 0 )		{			lastIndex = s.indexOf ( "%20" , startIndex );			newString.append ( s.substring ( startIndex , lastIndex ) );			newString.append ( " " );			startIndex = lastIndex + 3;		}		newString.append ( s.substring ( startIndex ) );		s = newString.toString ();		newString = new StringBuffer ();		startIndex = 0;		lastIndex = 0;		newString = new StringBuffer ();		while ( s.indexOf ( "%26" , startIndex ) >= 0 )		{			lastIndex = s.indexOf ( "%26" , startIndex );			newString.append ( s.substring ( startIndex , lastIndex ) );			newString.append ( "&" );			startIndex = lastIndex + 3;		}		newString.append ( s.substring ( startIndex ) );		return newString.toString ();	}}